init(_props, cx) {
  if (_props?.footer) return;
  cx.spawn(async cx => {
    for (;;) {
      const command = await nextCommand();
      if (command === "toggle-details") this.toggleDetails();
      else if (command === "detailed-on") setShared(DETAILS, true);
      else if (command === "detailed-off") setShared(DETAILS, false);
    }
  });
}

toggleDetails() {
  setShared(DETAILS, shared(DETAILS) !== true);
}

detailsButton(t) {
  const on = shared(DETAILS) === true;
  return this.button("detailed-view-toggle", "detailed-view", () => this.toggleDetails(), {
    size: 24, icon: 14, color: on ? t.foreground : t.dim,
    tip: on ? "Compact view" : "Detailed view",
  }).when(on, el => el.bg(t.raised));
}

agentsButton(t) {
  const on = !find(layout(), "agents")?.hidden;
  return this.button("agents-view-toggle", "agents-toggle", () => run("layout.toggle", { id: "agents" }), {
    size: 24, icon: 16, color: on ? t.foreground : t.dim,
    tip: on ? "Hide Agents and Idle" : "Show Agents and Idle",
  }).when(on, el => el.bg(t.raised));
}

.child(h_flex().flex_none().gap(2).items_center()
  .child(this.detailsButton(t))
  .child(this.button("sidebar-toggle", "sidebar", toggleSidebar, { tip: "Hide sidebar" })));

cx.spawn(async cx => {
  for (;;) {
    const command = await nextCommand();
    if (command.startsWith("toggle-details:")) this.toggleDetails(command.slice("toggle-details:".length), cx);
    else if (command.startsWith("open-pane:")) {
      const pane = panes().find(p => p.pane === command.slice("open-pane:".length));
      if (pane) this.openPanel(pane);
    }
  }
});

const detailed = shared(DETAILS) === true;
const closedDetails = new Set(Array.isArray(shared(CLOSED_DETAILS)) ? shared(CLOSED_DETAILS) : []);
const addDetails = (out, space) => {
  if (!detailed || closedDetails.has(space.id)) return;
  const tabs = tabGroups(space, ps);
  for (const [index, group] of tabs.entries()) {
    const h = 14 + Math.max(1, group.panes.length) * 26 + (group.tab.named && group.panes.length > 1 ? 16 : 0);
    out.push({ key: `details-${group.tab.id}`, h, el: () => this.tabDetails(space, group, ps, t, h, index === tabs.length - 1) });
  }
};

for (const r of trees) {
  out.push({ key: `tree-${r.w.id}`, h: H.tree, el: () => this.worktree(r, t) });
  addDetails(out, r.w);
}

}

toggleDetails(id, cx) {
  if (!spaces().some(space => space.id === id)) return;
  const closed = new Set(Array.isArray(shared(CLOSED_DETAILS)) ? shared(CLOSED_DETAILS) : []);
  closed.has(id) ? closed.delete(id) : closed.add(id);
  setShared(CLOSED_DETAILS, [...closed]);
  cx.notify();
}

detailsChevron(space, t) {
  const closed = shared(CLOSED_DETAILS);
  const open = !(Array.isArray(closed) && closed.includes(space.id));
  return div().id(`details-fold-${space.id}`).size(16).flex_none().flex().items_center().justify_center().rounded(R)
    .text_color(t.dim).hover(s => s.bg(t.input).text_color(t.foreground))
    .tooltip(open ? "Collapse terminals" : "Expand terminals")
    .on_mouse_down("left", (_e, cx) => cx.stop_propagation())
    .on_mouse_up("left", (_e, cx) => cx.stop_propagation())
    .on_click((_e, cx) => { cx.stop_propagation(); this.toggleDetails(space.id, cx); })
    .child(svg(`${ICONS}/chevron-${open ? "down" : "right"}.svg`).size(10));
}

openPanel(pane) {
  focusPanel(pane, panes(), run);
}

tabDetails(space, group, allPanes, t, height, last) {
  const { tab, panes: panels } = group;
  const on = space.active && tab.active;
  const stop = (_e, cx) => cx.stop_propagation();
  const glyph = pane => {
    const program = pane.program;
    if (program?.icon) return program.tint
      ? svg(program.icon).size(14).text_color(t.muted)
      : image(program.icon).size(14);
    return svg(`${ICONS}/${pane.terminal ? "terminal" : "file-text"}.svg`).size(14).text_color(t.muted);
  };
  // One rounded branch per tab; its short marker never stretches with splits.
  const join = (height - 8) / 2;
  const ink = mix(t.foreground, 0.16, t.chrome);
  return div().relative().h(height).pl(32).pr(8).pb(8)
    .child(div().absolute().left(22).top(-4).w(1).h(last ? join : height + 4).bg(ink))
    .child(div().absolute().left(22).top(join - 4).w(10).h(4)
      .border_l(1).border_b(1).border_color(ink).rounded_bl(4))
    .child(v_flex().id(`details-tab-${tab.id}`).relative().h_full().min_w(0).py(3).px(3).rounded(R)
      .when(on, el => el.bg(t.raised))
      .when(!on, el => el.bg(mix(t.foreground, 0.025, t.chrome)).hover(s => s.bg(t.hover)))
      .child(div().absolute().left(0).top(join - 11).w(2).h(22).rounded_full().bg(on ? t.accent : ink))
      .on_mouse_down("left", stop)
      .on_mouse_up("left", stop)
      .on_click(() => {
        const zoomed = panels.find(pane => pane.zoomed);
        if (zoomed) run("pane.zoom", { pane: zoomed.pane });
        run("tab.select", { id: tab.id });
      })
      .on_mouse_down("right", (_e, cx) => {
        cx.stop_propagation();
        openOverlay({ mod: "menu", kind: "popup", width: 200, props: { tab: "tab", target: { id: tab.id, space: space.id } } });
      })
      .when(tab.named && panels.length > 1, el => el.child(div().h(16).px(5).min_w(0).truncate().text_size(10).text_color(t.muted).tooltip(tab.name).child(tab.name)))
      .children(panels.map(pane => {
        const label = panelLabel(pane, tab, panels.length);
        const focused = on && pane.focused;
        const tip = [label, pane.title !== label && pane.title, pane.cwd].filter(Boolean).join("\n");
        return h_flex().id(`details-pane-${pane.pane}`).h(26).flex_none().min_w(0).px(5).gap(7).items_center().rounded(R)
          .text_size(12).text_color(focused ? t.foreground : t.muted)
          .when(focused, el => el.bg(t.selected))
          .hover(s => s.bg(t.hover).text_color(t.foreground)).tooltip(tip)
          .on_mouse_down("left", stop).on_mouse_up("left", stop)
          .on_click((_e, cx) => { cx.stop_propagation(); this.openPanel(pane); })
          .child(h_flex().size(16).flex_none().items_center().justify_center().child(glyph(pane)))
          .child(div().flex_1().min_w(0).truncate().child(label))
          .when(Boolean(pane.status) && pane.status !== "idle", el => el.child(dot(t, pane.status, 7, 9)));
      }))
      .when(panels.length === 0, el => el.child(h_flex().h(26).px(5).gap(7).items_center().text_size(12).text_color(t.dim)
        .child(svg(`${ICONS}/terminal.svg`).size(14)).child(tab.named ? tab.name : "Terminal"))));

// Every row identifies its space; only an actual session name adds a subtitle.
// Resolve each agent independently, including agents sharing a split tab.
const tabs = new Map(spaces().flatMap(s => s.tabs).map(tab => [tab.id, tab]));
const detail = new Map(list.map(a => [a.address, sessionName(tabs.get(a.tab), a)]));
